(() => {
  'use strict';
  const G = window.EloGuided, M = window.EloModel, e = M.escape;
  const action = (label, step, cls = 'secondary') => `<button type="button" class="button ${cls}" data-action="guidedStep" data-step="${step}">${label}</button>`;
  function bar(item, step) {
    if (!item.guided) return `<div class="guided-invitation"><div><strong>Do atendimento à peça processual.</strong><p>Crie uma petição inicial ou contestação guiada a partir deste contexto.</p></div><button class="button primary" data-action="newGuided">Criar peça guiada →</button></div>`;
    const req = G.requirements(item), count = req.filter(r => r.done).length;
    return `<div class="guided-bar"><div class="guided-label"><span class="eyebrow">CONSTRUÇÃO GUIADA</span><strong>${e(G.types[item.guided.type])}</strong><span>Procedimento comum · CPC</span></div><nav class="guided-steps" aria-label="Etapas da construção">${(item.fullDocument ? [['document', 'Documento completo'], ['check', 'Conferência']] : [['data', 'Dados da peça'], ['document', 'Documento final'], ['check', 'Conferência']]).map(([key, title], i) => `<button data-action="guidedStep" data-step="${key}" class="${step === key ? 'active' : ''}" aria-current="${step === key ? 'step' : 'false'}"><span>${i + 1}</span>${title}${key === 'check' ? `<small>${count}/${req.length}</small>` : ''}</button>`).join('')}</nav></div>`;
  }
  function data(item, userId) {
    const f = item.guided.fields, editable = M.canEdit(item, userId), initial = item.guided.type === 'initial';
    const field = (id, label, help, multiline = false) => `<label class="guided-field ${multiline ? 'wide' : ''}" for="guided-${id}"><span>${label}</span>${multiline ? `<textarea id="guided-${id}" data-guided-field="${id}" rows="4" maxlength="10000" ${editable ? '' : 'readonly'}>${e(f[id])}</textarea>` : `<input id="guided-${id}" data-guided-field="${id}" value="${e(f[id])}" maxlength="2000" ${editable ? '' : 'readonly'}>`}<small>${help}</small></label>`;
    return `<div class="guided-data-layout"><section class="content-card guided-form"><div class="section-heading"><div><span class="eyebrow">01 / DADOS DA PEÇA</span><h2>Comece pelo contexto processual.</h2></div><span id="saveStatus" role="status">Salvo neste navegador</span></div><p>Estes dados compõem o documento final. O modelo cobre o procedimento comum cível; outros procedimentos exigem adaptação.</p><div class="guided-fields">${field('juizo', 'Juízo e comarca', 'Confira competência, vara e local de distribuição.')}${initial ? field('acao', 'Nome da ação', 'Identifique a pretensão que será desenvolvida.') : field('processo', 'Número do processo', 'Confira o número e a identificação nos autos.')}${field('autor', 'Autor(es) — qualificação', 'Nome, estado civil, união estável, profissão, CPF/CNPJ, e-mail, domicílio e residência, conforme o caso. Registre eventuais lacunas.', true)}${field('reu', 'Réu(s) — qualificação', 'Identifique cada parte e os dados disponíveis. Uma lacuna justificada deve ser analisada pela advogada.', true)}${field('representacao', 'Representação processual', 'Identifique quem representa a parte, a procuração ou a hipótese legal aplicável.', true)}${initial ? field('valor', 'Valor da causa', 'Informe moeda e valor. O critério e o cálculo precisam de conferência.') + field('conciliacao', 'Conciliação ou mediação', 'Redija a manifestação do autor que constará na peça.', true) : ''}${field('localData', 'Local e data', 'Texto de encerramento da peça.')}${field('assinatura', 'Identificação da advogada ou do advogado', 'Nome e OAB/UF. Este campo não produz uma assinatura eletrônica.', true)}</div><div class="guided-next">${action('Continuar para a redação →', 'document', 'primary')}</div></section><aside class="guided-aside"><section class="content-card"><span class="eyebrow">UM DOCUMENTO, DOIS ESPAÇOS</span><h2>Texto da peça.<br>Contexto da equipe.</h2><p>Os dados e a redação entram no Word e no PDF. Orientações, notas e justificativas da conferência ficam na EloJus.</p><div class="guided-stat"><strong>${G.requirements(item).filter(r => r.present && !r.manual).length}</strong><span>itens com dados preenchidos<br>Redação livre com conferência manual</span></div><p class="panel-footnote">O preenchimento não confirma a adequação jurídica. A aprovação exige revisão humana.</p></section>${notes(item, userId)}</aside></div>`;
  }
  function notes(item, userId) {
    const editable = M.canEdit(item, userId);
    return `<section class="guided-notes"><span class="eyebrow">SOMENTE NA ELOJUS</span><h3>Notas internas</h3><p>Este conteúdo não entra na prévia final nem na exportação.</p>${item.guided ? `<label class="sr-only" for="guidedNotes">Notas internas</label><textarea id="guidedNotes" data-guided-notes rows="7" maxlength="20000" ${editable ? '' : 'readonly'}>${e(item.guided.notes)}</textarea>` : item.sections.filter(s => s.scope === 'internal').map(s => `<label for="internal-${e(s.id)}">${e(s.title)}</label><textarea id="internal-${e(s.id)}" data-internal-section="${e(s.id)}" rows="5" ${editable ? '' : 'readonly'}>${e(s.text)}</textarea>`).join('')}${item.guided?.sourceId ? `<p class="panel-footnote">Contexto preservado de ${e(item.guided.sourceId)}.</p>` : ''}</section>`;
  }
  function check(item, userId) {
    const req = G.requirements(item), done = req.filter(r => r.done).length, editable = M.canEdit(item, userId), disabled = editable ? '' : 'disabled', fp = G.fingerprint(item);
    return `<section class="content-card guided-conference"><div class="conference-heading"><div><span class="eyebrow">${item.fullDocument ? '02' : '03'} / CONFERÊNCIA DOS REQUISITOS</span><h2>Confira o conteúdo. Registre a decisão.</h2><p>Confira cada requisito no texto livre da peça. A EloJus não identifica automaticamente se cada requisito está atendido. Cada marcação se refere à redação atual.</p></div><div class="conference-count"><strong>${done}<span>/${req.length}</span></strong><small>itens conferidos</small></div></div><div class="conference-progress" role="progressbar" aria-label="Conferência" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="${req.length}"><span style="width:${100 * done / req.length}%"></span></div><div class="requirements">${req.map((r, i) => `<article class="requirement ${r.done ? 'done' : ''}"><div class="requirement-number">${r.done ? '✓' : String(i + 1).padStart(2, '0')}</div><div class="requirement-detail"><h3>${e(r.title)}</h3><p>${e(r.basis)}</p><span class="requirement-presence">${r.manual ? (r.present ? 'Conferir manualmente no texto da peça' : 'Escreva o texto da peça e confira este requisito') : r.present ? 'Texto identificado · conferir conteúdo' : 'Conteúdo a completar ou hipótese a analisar'}</span>${r.status && r.status !== 'pending' && r.fingerprint !== fp ? '<p class="stale-check">Documento alterado. Refaça esta conferência.</p>' : ''}</div><div class="requirement-control"><label class="sr-only" for="requirement-${r.id}">Conferência: ${e(r.title)}</label><select id="requirement-${r.id}" data-requirement="${r.id}" ${disabled}><option value="pending">Pendente</option><option value="checked" ${r.fresh && r.status === 'checked' ? 'selected' : ''}>Conferido</option>${r.optional ? `<option value="na" ${r.fresh && r.status === 'na' ? 'selected' : ''}>Não se aplica</option>` : ''}${r.exception ? `<option value="exception" ${r.fresh && r.status === 'exception' ? 'selected' : ''}>Ressalva justificada</option>` : ''}</select>${r.fresh && ['na', 'exception'].includes(r.status) ? `<label for="reason-${r.id}">Justificativa interna</label><textarea id="reason-${r.id}" data-requirement-reason="${r.id}" rows="3" maxlength="2000" ${disabled}>${e(r.reason || '')}</textarea>` : ''}${r.fresh && r.status === 'checked' && !r.present ? '<small>Preencha o conteúdo para concluir este item.</small>' : ''}</div></article>`).join('')}</div>${item.fullDocument ? `<div class="annex-control"><strong>Documentos de apoio</strong><p>Confira as referências e a relação de documentos diretamente na peça. Em Fontes, você pode inserir referências como texto editável e revisar os vínculos.</p>${window.EloAttachments.index(item) ? `<div class="annex-generated"><strong>Arquivos vinculados para conferência</strong><br>${e(window.EloAttachments.index(item))}</div>` : ''}${window.EloAttachments.issues(item).length ? '<p class="attachment-warning">Há vínculos pendentes. Confira os trechos e arquivos em Fontes.</p>' : ''}</div>` : `<div class="annex-control"><label for="guidedAnnexes">Relação de documentos — incluída na peça</label><textarea id="guidedAnnexes" data-guided-annexes rows="4" ${editable ? '' : 'readonly'}>${e(item.guided.annexes)}</textarea><small>Use esta relação para documentos adicionais. Os arquivos vinculados em Fontes entram automaticamente no índice abaixo. Confira a correspondência e a juntada no sistema de destino; alterar os documentos requer nova conferência.</small>${window.EloAttachments.index(item) ? `<div class="annex-generated"><strong>Documentos vinculados ao caso</strong><br>${e(window.EloAttachments.index(item))}</div>` : ''}${window.EloAttachments.issues(item).length ? '<p class="attachment-warning">Há vínculos pendentes. Confira os trechos e arquivos em Fontes.</p>' : ''}</div>`}<div class="final-attestation"><label class="check-line"><input type="checkbox" id="guidedAttestation" ${item.guided.attestation?.key === G.reviewKey(item) && item.guided.attestation?.userId === 'marina' ? 'checked' : ''} ${editable && userId === 'marina' && done === req.length ? '' : 'disabled'}><span>Como revisora, conferi a peça, os documentos e as justificativas para esta versão.</span></label><p>${done < req.length ? 'Conclua os itens acima para habilitar a conferência final de Marina.' : userId !== 'marina' ? 'Marina registra a conferência final na visão de advogada.' : 'A aprovação interna continua separada da assinatura e do protocolo.'}</p></div><div class="conference-footer"><a href="${G.CPC}" target="_blank" rel="noopener">Consultar o CPC na fonte oficial ↗</a><div>${action('Voltar ao documento', 'document')}${item.status === 'review' && userId === 'marina' ? '<button class="button primary" data-action="approve">Aprovar minuta ✓</button>' : editable ? '<button class="button primary" data-action="submit">Enviar para revisão →</button>' : ''}</div></div><p class="panel-footnote">A conferência organiza o trabalho e não certifica admissibilidade, tempestividade ou adequação jurídica.</p></section>`;
  }
  function choose() { return `<p>Uma nova peça será criada com as orientações e o contexto deste caso. O documento de origem permanece disponível.</p><div class="guided-choices">${Object.entries(G.types).map(([type, title]) => `<button class="button guided-choice" data-action="createGuided" data-type="${type}"><span class="eyebrow">PROCEDIMENTO COMUM · CPC</span><strong>${title}</strong><span>${type === 'initial' ? 'Fatos, fundamentos, pedidos, provas, valor e conciliação.' : 'Tempestividade, preliminares, impugnação, fundamentos e pedidos.'}</span><b>Começar →</b></button>`).join('')}</div>`; }
  window.EloGuidedUI = { bar, data, notes, check, choose, guidance };
  function guidance(item) { return item.guided ? `<details class="writing-guidance"><summary>Sugestões para a redação</summary><p>Organize o texto livremente. Estes lembretes ficam fora do documento.</p>${[{ title: 'Endereçamento e identificação', help: 'Informe o juízo, a comarca e, quando houver, o número do processo. Confira a competência e o procedimento.' }, { title: 'Qualificação e representação', help: 'Identifique as partes, seus dados disponíveis e quem as representa. Escreva a qualificação no próprio documento.' }, ...G.templates(item.guided.type), ...(item.guided.type === 'initial' ? [{ title: 'Valor da causa e conciliação', help: 'Inclua o valor da causa, seu critério e a manifestação sobre conciliação ou mediação, conforme o caso.' }] : []), { title: 'Encerramento', help: 'Inclua local, data e identificação profissional. O texto não produz assinatura eletrônica.' }].map(s => `<div><strong>${e(s.title)}</strong><p>${e(s.help)}</p></div>`).join('')}</details>` : ''; }
})();
